#ifndef MYLIB_MINIMAP_GLSL
#define MYLIB_MINIMAP_GLSL

// Faces of the extra top element added to the block models (y = 1.25/16 inside the block):
// terrain.vsh draws them into a top-down map in the top-right corner of the screen.
const float MAP_MARK = 1.25 / 16.0;
const float MAP_BLOCKS = 128.0;   // blocks across the map, centered on the camera, north up
const float MAP_HEIGHT = 0.9;     // map height in NDC: 45% of the screen height
const float MAP_MARGIN = 0.04;

bool isMapVertex(vec3 position) {
    return abs(fract(position.y) - MAP_MARK) < 1.0e-4;
}

// Half size and center of the map square in NDC (needs Globals for ScreenSize).
vec2 mapHalf() {
    return vec2(MAP_HEIGHT * 0.5 * ScreenSize.y / ScreenSize.x, MAP_HEIGHT * 0.5);
}

vec2 mapCenter() {
    return vec2(1.0) - mapHalf() - vec2(MAP_MARGIN * ScreenSize.y / ScreenSize.x, MAP_MARGIN);
}

#endif

