layout(location = 4) out float chunkVisibility;
layout(location = 5) out vec4 screenClip;
layout(location = 6) out float mapFace;

gl_Position = ProjMat * ModelViewMat * vec4(pos, 1.0);
if (isMapVertex(Position)) {
    // Top-down orthographic view: east to the right, north up, higher blocks in front (depth is reversed).
    vec2 uv = vec2(pos.x, -pos.z) / (MAP_BLOCKS * 0.5);
    gl_Position = vec4(mapCenter() + uv * mapHalf(), 0.5 + 0.4 * clamp(pos.y / 256.0, -1.0, 1.0), 1.0);
    screenClip = gl_Position;
    mapFace = 1.0;
    sphericalVertexDistance = 0.0;
    cylindricalVertexDistance = 0.0;
    vertexColor = Color;   // no lightmap: the map stays lit at night
    texCoord0 = UV0;
    chunkVisibility = 1.0;
    return;
}
screenClip = gl_Position;
mapFace = 0.0;

layout(location = 4) in float chunkVisibility;
layout(location = 5) in vec4 screenClip;
layout(location = 6) in float mapFace;

void main() {
    // The map square only takes map faces, and map faces stay in it.
    vec2 mapUV = (screenClip.xy / screenClip.w - mapCenter()) / mapHalf();
    bool inMap = all(lessThan(abs(mapUV), vec2(1.0)));
    if (inMap != (mapFace > 0.5)) {
        discard;
    }

if (mapFace > 0.5 && length(mapUV) < 0.03) {
    color = vec4(1.0, 0.0, 0.0, 1.0);   // the camera, at the center of the map
}

